import{_ as d,o as e,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const f=JSON.parse('{"title":"Keyboard shortcuts","description":"Every keyboard shortcut on a board, for tools, sticky notes, navigation, selection, editing, and collaboration.","frontmatter":{"title":"Keyboard shortcuts","description":"Every keyboard shortcut on a board, for tools, sticky notes, navigation, selection, editing, and collaboration.","type":"reference"},"headers":[],"relativePath":"board/keyboard-shortcuts.md","filePath":"board/keyboard-shortcuts.md"}'),c={name:"board/keyboard-shortcuts.md"};function a(i,t,n,s,l,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>Every keyboard shortcut on a board, for tools, sticky notes, navigation, selection, editing, and collaboration.</p><p><strong>Conventions.</strong> Each entry lists the Mac key first, then Windows and Linux. To see the list in the app, press <code>⌘+/</code> / <code>Ctrl+/</code> on a board.</p><p><strong>Single-key tools</strong> such as <code>S</code>, <code>T</code>, <code>M</code>, <code>/</code>, and <code>E</code> work only when nothing is selected and you can edit the board. With an item selected, typing a letter starts editing that item instead.</p><h2 id="most-used" tabindex="-1">Most used <a class="header-anchor" href="#most-used" aria-label="Permalink to &quot;Most used&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Select tool</td><td><code>V</code> or <code>Escape</code></td></tr><tr><td>Add a sticky note</td><td><code>S</code></td></tr><tr><td>Finish a sticky note and start the next</td><td><code>Tab</code> or <code>⌘+Enter</code> / <code>Ctrl+Enter</code> while typing</td></tr><tr><td>Add a text box</td><td><code>T</code></td></tr><tr><td>Zoom to fit the whole board</td><td><code>Shift+1</code></td></tr><tr><td>Find on the board</td><td><code>⌘+F</code> / <code>Ctrl+F</code></td></tr><tr><td>Undo</td><td><code>⌘+Z</code> / <code>Ctrl+Z</code></td></tr><tr><td>Redo</td><td><code>⌘+Shift+Z</code> / <code>Ctrl+Shift+Z</code></td></tr><tr><td>Show keyboard shortcuts</td><td><code>⌘+/</code> / <code>Ctrl+/</code></td></tr></tbody></table><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Pan</td><td>Hold <code>Space</code> and drag</td></tr><tr><td>Hand tool (drag to pan)</td><td><code>H</code></td></tr><tr><td>Pan sideways</td><td>Hold <code>Shift</code> and scroll</td></tr><tr><td>Zoom at the pointer</td><td>Hold <code>⌘</code> / <code>Ctrl</code> and scroll or pinch</td></tr><tr><td>Zoom in</td><td><code>⌘+=</code> / <code>Ctrl+=</code></td></tr><tr><td>Zoom out</td><td><code>⌘+-</code> / <code>Ctrl+-</code></td></tr><tr><td>Zoom to 100%</td><td><code>⌘+0</code> / <code>Ctrl+0</code></td></tr><tr><td>Zoom to fit</td><td><code>Shift+1</code></td></tr><tr><td>Zoom to selection</td><td><code>Shift+2</code></td></tr><tr><td>Find on the board</td><td><code>⌘+F</code> / <code>Ctrl+F</code></td></tr><tr><td>Next or previous match in find</td><td><code>Enter</code> or <code>Shift+Enter</code></td></tr><tr><td>Stop following a teammate</td><td><code>Escape</code></td></tr></tbody></table><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Select everything</td><td><code>⌘+A</code> / <code>Ctrl+A</code></td></tr><tr><td>Lasso select</td><td>Hold <code>Option</code> / <code>Alt</code> and drag a loop on empty canvas</td></tr><tr><td>Clear the selection</td><td><code>Escape</code></td></tr><tr><td>Nudge 1 pixel</td><td><code>←</code> <code>→</code> <code>↑</code> <code>↓</code></td></tr><tr><td>Nudge 10 pixels</td><td><code>Shift+←</code> <code>Shift+→</code> <code>Shift+↑</code> <code>Shift+↓</code></td></tr></tbody></table><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Edit the selected sticky note, shape, or text</td><td><code>Enter</code> or <code>F2</code></td></tr><tr><td>Finish editing text</td><td><code>Escape</code></td></tr><tr><td>Add a sticky note next to the selected one</td><td><code>⌘+Enter</code> / <code>Ctrl+Enter</code></td></tr><tr><td>Paste text as sticky notes, one per line or cell</td><td><code>⌘+V</code> / <code>Ctrl+V</code></td></tr><tr><td>Copy</td><td><code>⌘+C</code> / <code>Ctrl+C</code></td></tr><tr><td>Cut</td><td><code>⌘+X</code> / <code>Ctrl+X</code></td></tr><tr><td>Paste</td><td><code>⌘+V</code> / <code>Ctrl+V</code></td></tr><tr><td>Duplicate</td><td><code>⌘+D</code> / <code>Ctrl+D</code></td></tr><tr><td>Delete</td><td><code>Delete</code> or <code>Backspace</code></td></tr></tbody></table><h2 id="formatting" tabindex="-1">Formatting <a class="header-anchor" href="#formatting" aria-label="Permalink to &quot;Formatting&quot;">​</a></h2><p>These work while you edit text.</p><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Bold</td><td><code>⌘+B</code> / <code>Ctrl+B</code></td></tr><tr><td>Italic</td><td><code>⌘+I</code> / <code>Ctrl+I</code></td></tr><tr><td>Underline</td><td><code>⌘+U</code> / <code>Ctrl+U</code></td></tr><tr><td>Insert link</td><td><code>⌘+K</code> / <code>Ctrl+K</code></td></tr></tbody></table><h2 id="objects" tabindex="-1">Objects <a class="header-anchor" href="#objects" aria-label="Permalink to &quot;Objects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Sticky note</td><td><code>S</code></td></tr><tr><td>Text box</td><td><code>T</code></td></tr><tr><td>Section (drag, or click for a default size)</td><td><code>Shift+S</code></td></tr><tr><td>Rectangle</td><td><code>R</code></td></tr><tr><td>Ellipse</td><td><code>O</code></td></tr><tr><td>Line</td><td><code>L</code></td></tr><tr><td>Arrow</td><td><code>Shift+L</code></td></tr><tr><td>Connector</td><td><code>X</code></td></tr><tr><td>Marker (stays on until <code>Escape</code>)</td><td><code>M</code></td></tr><tr><td>Highlighter</td><td><code>Shift+M</code></td></tr><tr><td>Eraser (drag across strokes)</td><td><code>Shift+E</code></td></tr><tr><td>Draw a straight line</td><td>Hold <code>Shift</code> while drawing</td></tr><tr><td>Laser pointer</td><td><code>Shift+K</code></td></tr><tr><td>Group</td><td><code>⌘+Option+G</code> / <code>Ctrl+Alt+G</code></td></tr><tr><td>Ungroup</td><td><code>⌘+Shift+Option+G</code> / <code>Ctrl+Shift+Alt+G</code></td></tr><tr><td>Bring forward</td><td><code>⌘+↑</code> / <code>Ctrl+↑</code></td></tr><tr><td>Send backward</td><td><code>⌘+↓</code> / <code>Ctrl+↓</code></td></tr><tr><td>Bring to front</td><td><code>⌘+Shift+↑</code> / <code>Ctrl+Shift+↑</code></td></tr><tr><td>Send to back</td><td><code>⌘+Shift+↓</code> / <code>Ctrl+Shift+↓</code></td></tr><tr><td>Tidy up into a grid (two or more items)</td><td><code>Option+Shift+T</code> / <code>Alt+Shift+T</code></td></tr></tbody></table><h2 id="collaboration" tabindex="-1">Collaboration <a class="header-anchor" href="#collaboration" aria-label="Permalink to &quot;Collaboration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Comment on the selection, or click to place one</td><td><code>⌘+Option+M</code> / <code>Ctrl+Alt+M</code></td></tr><tr><td>Cursor chat</td><td><code>/</code></td></tr><tr><td>Emotes</td><td><code>E</code>, then <code>1</code> to <code>6</code> to send</td></tr></tbody></table><h2 id="view" tabindex="-1">View <a class="header-anchor" href="#view" aria-label="Permalink to &quot;View&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Show keyboard shortcuts</td><td><code>⌘+/</code> / <code>Ctrl+/</code></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/board/">Board</a> for an overview of the tools.</li><li><a href="/docs/board/stickies-shapes-connectors.html">Stickies, shapes, and connectors</a> to add and arrange content.</li><li><a href="/docs/board/facilitate-a-session.html">Facilitate a session</a> for chat, emotes, and comments.</li></ul>',23)])])}const u=d(c,[["render",a]]);export{f as __pageData,u as default};
